package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FamilyNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property family name of user profile ")
  void test_family_name_v_o_builder() {
    Assertions.assertFalse(FamilyNameVO.nullValue().getFamilyName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(FamilyNameVO.tryFrom(null).getFamilyName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", FamilyNameVO.from("one").getFamilyName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> FamilyNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", FamilyNameVO.from("one").toString());
  }
}
